package Program.service; import Program.model.Expense; import Program.utils.FileManager; import java.time.LocalDate; import java.util.*;
public class ExpenseService extends TransactionService { public Expense add(String user,double amount,String category,LocalDate date,String desc){Expense e=new Expense(UUID.randomUUID().toString(),user,amount,category,date,desc);FileManager.append("expenses.txt",record(e));return e;} public void update(Expense e,double amount,String cat,LocalDate date,String desc){e.setAmount(amount);e.setCategory(cat);e.setDate(date);e.setDescription(desc);FileManager.update("expenses.txt",s->s.startsWith(e.getId()+"|"),record(e));} public void delete(String id){FileManager.delete("expenses.txt",s->s.startsWith(id+"|"));}}
